package com.vandorlabs.neoforge.gear;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Survival dig timing and real asynchronous terrain/actor custody at a fractional rotating endpoint. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearHarvestChecks {
    private static final BlockPos ROOT=new BlockPos(15,110,15),SOURCE=ROOT.below(2);private static ServerLevel world;private static Actor actor;private static boolean running,faulted;private static int stage,ticks,checks,endpointQueries,endpointBuilds;private static java.util.concurrent.CompletableFuture<Void> partial;
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211481),"NativeGearHarvest"));}}
    private static String phase(){return System.getProperty("vandorlabs.gearHarvestPhase","");}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Harvest "+phase()+" stage="+stage+" ticks="+ticks+": "+why);}
    private static NativeGearEntity root(){var root=NativeGearFormation.at(world,ROOT);need(root!=null&&!root.inert(),"healthy root");return root;}
    private static int diamonds(){int count=0;var payload=root().payload();if(payload!=null&&!payload.materialized())for(var cell:payload.cells())if(NativeGearSnapshot.stage(world,cell,false) instanceof ChestBlockEntity chest)for(int slot=0;slot<chest.getContainerSize();slot++)if(chest.getItem(slot).is(Items.DIAMOND))count+=chest.getItem(slot).getCount();return count;}
    private static List<net.minecraft.world.entity.item.ItemEntity> drops(){return world.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(ROOT).inflate(12));}
    private static boolean aim(){var root=root();var boxes=root.payload().boxes(root,root.progress());for(var box:boxes)for(var side:Direction.values()){var target=box.getCenter();var eye=target.add(Vec3.atLowerCornerOf(side.getNormal()).scale(3.5));var look=target.subtract(eye).normalize();actor.setPos(eye.x,eye.y-actor.getEyeHeight(),eye.z);actor.setYRot((float)Math.toDegrees(Math.atan2(-look.x,look.z)));actor.setXRot((float)-Math.toDegrees(Math.asin(look.y)));var hit=NativeGearHarvest.target(actor);if(hit!=null&&hit.owner()==root)return true;}return false;}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(phase().isEmpty())return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);for(int x=-1;x<=2;x++)for(int z=-1;z<=2;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}if(phase().equals("recover")){need(diamonds()==7&&root().payload()!=null&&!root().payload().materialized()&&root().blocked(),"ARMED cold rollback preserves original captured inventory");need(drops().isEmpty(),"rollback removes exact frozen native actor drops");root().authorize(actor);need(root().command(false),"recovered endpoint can retry harvest");stage=2;running=true;return;}
        for(int x=9;x<=23;x++)for(int y=104;y<=116;y++)for(int z=9;z<=23;z++)world.setBlock(new BlockPos(x,y,z),y==104?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),18);world.setBlock(ROOT.above(),Blocks.STONE.defaultBlockState(),3);actor.setPos(12,111,12);actor.setYRot(0);var stack=new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.ROTATING.id),2);var data=new CompoundTag();var choices=NativeGearSettings.defaults().choices();choices.putBoolean("RotatePayload",false);data.put(NativeGearItem.SETTINGS,choices);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);for(int p=0;p<2;p++){var support=ROOT.relative(Direction.DOWN,p-1);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(0,-.5,0),Direction.DOWN,support,false)).consumesAction(),"real supported Survival arm placement");}need(stack.isEmpty(),"two section items consumed");running=true;
    }catch(Throwable failure){fail(failure);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<800,"timeout "+root().error()+" progress="+root().progress()+" busy="+NativeGearJournal.busy(root()));if(stage==0){if(!root().controller()||root().assembly().columnHeight()!=2)return;world.setBlock(SOURCE,Blocks.CHEST.defaultBlockState(),3);var chest=(ChestBlockEntity)world.getBlockEntity(SOURCE);chest.setItem(0,new ItemStack(Items.DIAMOND,7));chest.getPersistentData().putByteArray("HarvestOpaque",new byte[128]);chest.setChanged();root().authorize(actor);need(root().command(false),"activate ordinary chest payload");stage=1;return;}
        if(stage==1){need(!root().blocked(),"ordinary capture stroke "+root().error());if(NativeGearJournal.busy(root())||root().progress()!=0||root().payload()==null)return;need(!root().payload().materialized()&&diamonds()==7&&world.getBlockState(SOURCE).isAir(),"fractional level endpoint retains sole captured inventory");need(root().payload().endpoint(root(),0).isEmpty(),"fixture is genuinely not a native grid endpoint");if(phase().equals("crash")){world.getServer().saveEverything(true,true,true);NativeGearJournal.testFault=where->{if(where.equals("checkpoint-durable")&&root().payload()==null&&!faulted){faulted=true;need(!drops().isEmpty(),"native actor checkpoint contains frozen planned drops");for(var drop:drops())need(NativeGearDropEscrow.held(drop),"durable ARMED drop still unusable");System.out.println("[vandorlabs][gear-harvest] crash PASS checks="+checks+" ARMED/nativeActorAndTerrainDurableBeforeAPPLIED/abruptHalt");System.out.flush();Runtime.getRuntime().halt(0);}};}NativeGearPayloadService.endpointProbe=(owner,step)->{if(owner.getBlockPos().equals(ROOT)){if(step.equals("query"))endpointQueries++;else endpointBuilds++;}};stage=2;ticks=0;return;}
        if(stage==2){if(root().payload()!=null&&!NativeGearJournal.busy(root())){actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND_AXE));need(aim(),"actual unoccluded captured-cell ray");var packet=new NativeGearHarvestPayload(ROOT,root().identity(),false);var buf=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),world.registryAccess());NativeGearHarvestPayload.CODEC.encode(buf,packet);need(buf.readableBytes()==25,"bounded dig intent bytes");var decoded=NativeGearHarvestPayload.CODEC.decode(buf);buf.release();if(!NativeGearJournal.busy(root()))need(NativeGearHarvest.dig(actor,decoded),"real Survival dig input accepted");if(ticks==1)need(diamonds()==7,"first Survival tick cannot instantly harvest Chest");}
            if(phase().equals("crash")&&faulted){for(var drop:drops())need(NativeGearDropEscrow.held(drop),"uncommitted drops frozen against player/hopper/tick");if(partial!=null&&partial.isDone()){partial.join();System.out.println("[vandorlabs][gear-harvest] crash PASS checks="+checks+" realARMED/rootOnlyPartialSave/frozenNativeDrops/abruptHalt");System.out.flush();Runtime.getRuntime().halt(0);}return;}
            need(!root().blocked(),"harvest journal "+root().error());if(root().payload()!=null||NativeGearJournal.busy(root()))return;int diamond=0,chest=0;for(var drop:drops()){need(!NativeGearDropEscrow.held(drop),"drop released only after journal retirement");if(drop.getItem().is(Items.DIAMOND))diamond+=drop.getItem().getCount();if(drop.getItem().is(Items.CHEST))chest+=drop.getItem().getCount();}need(diamond==7&&chest==1,"exactly one Chest and seven diamonds, no captured duplicate");need(world.getBlockState(SOURCE).isAir()&&NativeGearFormation.at(world,ROOT.below())!=null,"source AIR and original arm preserved");need(endpointQueries>10&&endpointBuilds<=1,"stable fractional endpoint derivation cached queries="+endpointQueries+" builds="+endpointBuilds);NativeGearPayloadService.endpointProbe=null;System.out.println("[vandorlabs][gear-harvest] endpoint beforeBuilds="+endpointQueries+" afterBuilds="+endpointBuilds);System.out.println("[vandorlabs][gear-harvest] "+phase()+" PASS checks="+checks+" actualRay/SurvivalTiming/asyncHARVEST/nativeActorBarrier/exactLoot/lastCellRemoval");running=false;event.getServer().halt(false);}
    }catch(Throwable failure){fail(failure);}}
    private static void fail(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][gear-harvest] "+phase()+" FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
